#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
const string R[32]={"zero","at","v0","v1","a0","a1","a2","a3","t0","t1","t2","t3","t4","t5","t6","t7","s0","s1","s2","s3","s4","s5","s6","s7","t8","t9","k0","k1","gp","sp","fp","ra"};
int32_t s16(uint32_t x){uint32_t n=x&0xffff;return n&0x8000?(int32_t)n-65536:(int32_t)n;} uint32_t u32(const vector<uint8_t>&b,size_t i){return (uint32_t)b[i]<<24|(uint32_t)b[i+1]<<16|(uint32_t)b[i+2]<<8|b[i+3];}
struct MHC{uint32_t ts,ds;vector<uint8_t> text,data;};
MHC readFile(string path){ifstream f(path,ios::binary);if(!f)throw runtime_error("cannot open input");vector<uint8_t>b((istreambuf_iterator<char>(f)),{});if(b.size()>=4&&string((char*)b.data(),4)=="MHC1"){if(b.size()<24)throw runtime_error("incomplete binary header");uint32_t v=u32(b,4),ts=u32(b,8),ds=u32(b,12),tl=u32(b,16),dl=u32(b,20);if(v!=1||b.size()!=24+tl+dl)throw runtime_error("invalid binary MHC header");return {ts,ds,{b.begin()+24,b.begin()+24+tl},{b.begin()+24+tl,b.end()}};} string x(b.begin(),b.end());istringstream in(x);string line,mode;map<string,string>h;vector<uint8_t>t,d;while(getline(in,line)){if(line=="TEXT"||line=="DATA"){mode=line;continue;}if(line.empty())continue;if(mode.empty()){size_t p=line.find(' ');h[line.substr(0,p)]=line.substr(p+1);}else if(mode=="TEXT"){if(line.size()!=32)throw runtime_error("invalid ASCII text line");uint32_t w=stoul(line,nullptr,2);t.push_back(w>>24);t.push_back(w>>16);t.push_back(w>>8);t.push_back(w);}else d.push_back(stoul(line,nullptr,2));}if(h["MHC-ASCII"]!="1")throw runtime_error("not MHC-ASCII version 1");return {(uint32_t)stoul(h["TEXT_START"],nullptr,0),(uint32_t)stoul(h["DATA_START"],nullptr,0),t,d};}
string hex(uint32_t x){stringstream s;s<<"0x"<<uppercase<<setfill('0')<<setw(8)<<std::hex<<x;return s.str();}
int main(int argc,char**argv){try{if(argc<2){cerr<<"usage: disassembler_cpp input [output]\n";return 1;}string out=argc>2?argv[2]:"reconstructed.asm";MHC m=readFile(argv[1]);vector<uint32_t>w;for(size_t i=0;i<m.text.size();i+=4)w.push_back(u32(m.text,i));map<uint32_t,string>lab;int n=0;for(size_t i=0;i<w.size();++i){uint32_t pc=m.ts+i*4,op=w[i]>>26;if(op==4||op==5)lab[pc+4+s16(w[i])*4]="L"+to_string(n++);else if(op==2)lab[((pc+4)&0xf0000000)|((w[i]&0x03ffffff)<<2)]="L"+to_string(n++);}ofstream o(out);o<<"# Reconstructed by disassembler_cpp\n.data\n# data starts at "<<hex(m.ds)<<"\n.byte ";for(size_t i=0;i<m.data.size();++i){if(i)o<<", ";o<<(int)m.data[i];}o<<"\n\n.text\n# text starts at "<<hex(m.ts)<<"\n";for(size_t i=0;i<w.size();++i){uint32_t z=w[i],pc=m.ts+i*4,op=z>>26;if(lab.count(pc))o<<lab[pc]<<":\n";if(op==0){int rs=z>>21&31,rt=z>>16&31,rd=z>>11&31,f=z&63;if(f==0xc)o<<"syscall\n";else if(f==0x10)o<<"mfhi $"<<R[rd]<<"\n";else if(f==0x1a)o<<"div $"<<R[rs]<<", $"<<R[rt]<<"\n";else if(f==0x20||f==0x21||f==0x22)o<<((f==0x20)?"add":f==0x21?"addu":"sub")<<" $"<<R[rd]<<", $"<<R[rs]<<", $"<<R[rt]<<"\n";else o<<".word "<<hex(z)<<"\n";}else if(op==2){uint32_t q=((pc+4)&0xf0000000)|((z&0x03ffffff)<<2);o<<"j "<<(lab.count(q)?lab[q]:hex(q))<<"\n";}else if(op==4||op==5){uint32_t q=pc+4+s16(z)*4;o<<(op==4?"beq":"bne")<<" $"<<R[z>>21&31]<<", $"<<R[z>>16&31]<<", "<<(lab.count(q)?lab[q]:hex(q))<<"\n";}else if(op==0xf)o<<"lui $"<<R[z>>16&31]<<", 0x"<<uppercase<<setw(4)<<setfill('0')<<hex<< (z&0xffff)<<dec<<"\n";else if(op==8||op==9)o<<(op==8?"addi":"addiu")<<" $"<<R[z>>16&31]<<", $"<<R[z>>21&31]<<", "<<s16(z)<<"\n";else if(op==0xd)o<<"ori $"<<R[z>>16&31]<<", $"<<R[z>>21&31]<<", 0x"<<uppercase<<setw(4)<<setfill('0')<<hex<<(z&0xffff)<<dec<<"\n";else o<<".word "<<hex(z)<<"\n";}cout<<"wrote "<<out<<"\n";}catch(exception&e){cerr<<"disassembler error: "<<e.what()<<'\n';return 1;}}
